        mode=image_mode,
    )
    assert (
        reader._encoding_ratio >= expected_ratio
        and reader._encoding_ratio <= expected_ratio * 1.5
    ), "encoding ratio is out of expected bound"
    data_size = reader.estimate_inmemory_data_size()
    assert (
