    if isinstance(pipe, Dataset):
        assert (
            len(pipe._plan._stages_before_snapshot) == num_stages_expected
        ), pipe._plan._stages_before_snapshot
    else:
        assert (
            len(pipe._optimized_stages) == num_stages_expected
        ), pipe._optimized_stages


